  function countryName(c,lang){return (COUNTRY_NAMES[lang]&&COUNTRY_NAMES[lang][c.name])||c.name}
  function countryRegion(c,lang){return (REGION_NAMES[lang]&&REGION_NAMES[lang][c.region])||c.region}
  function countryScope(c,lang){return (SCOPE_NAMES[lang]&&SCOPE_NAMES[lang][c.scope])||localizedText(c.scope,lang)}
  function productName(x,lang){return (PRODUCT_NAMES[lang]&&PRODUCT_NAMES[lang][x])||x}
  function countryFlagHtml(c,cls=''){const asset=String(c.flagAsset||'').trim();const alt=countryName(c,localStorage.getItem(langStore)||'en');if(asset)return `<img class="flagEmojiAsset ${esc(cls)}" src="${esc(asset)}" alt="${esc(alt)} flag" loading="lazy">`;return `<span class="flagEmojiGlyph ${esc(cls)}" aria-label="${esc(alt)} flag">${esc(c.flag||'')}</span>`;}

  function countryCard(c){const lang=localStorage.getItem(langStore)||'en';return `<a class="countryCard" href="country.html?country=${encodeURIComponent(c.name)}"><div class="countryCardTop"><span class="countryFlagMini">${countryFlagHtml(c)}</span><span class="regionPill">${esc(countryRegion(c,lang))}</span></div><div class="countryName">${esc(countryName(c,lang))}</div><div class="countryAuthorityRow">${authorityLogoHtml(c)}<span class="authorityName">${esc(c.authority||'Regulator')}</span><span class="countryOpen">↗</span></div></a>`;}

  function setupCountries(){
    const grid=$('#countryGrid');if(!grid)return;const search=$('#countrySearch'),more=$('#moreMarketsBtn');let region='All',expanded=false;
    const draw=()=>{
      const q=(search?.value||'').toLowerCase().trim();
      const langNow=localStorage.getItem(langStore)||'en';const list=uniqueCountries.filter(c=>(region==='All'||c.region===region)&&`${countryName(c,langNow)} ${countryRegion(c,langNow)} ${c.authority} ${countryScope(c,langNow)} ${(c.products||[]).map(x=>productName(x,langNow)).join(' ')}`.toLowerCase().includes(q));
      const limit=(expanded||q)?list.length:12;const emptyLang=localStorage.getItem(langStore)||'en';const emptyMsg=emptyLang==='ar'?'لم يتم العثور على أسواق مطابقة.':emptyLang==='zh'?'未找到匹配的市场。':'No matching markets found.';grid.innerHTML=list.slice(0,limit).map(countryCard).join('')||`<div class="empty">${emptyMsg}</div>`;
      if($('#countryCount'))$('#countryCount').textContent=countries.length;
      if(more){const hidden=list.length>12&&!expanded&&!q;more.style.display=list.length>12?'inline-flex':'none';more.querySelector('span').textContent=hidden?T[localStorage.getItem(langStore)||'en'].moreMarkets:T[localStorage.getItem(langStore)||'en'].showLessMarkets;more.querySelector('b').textContent=hidden?'+':'−';}
    };
    window.__afaqDrawCountries=draw;
    $$('.filter').forEach(b=>b.addEventListener('click',()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');region=b.dataset.region||'All';expanded=false;draw()}));
    search?.addEventListener('input',()=>{expanded=false;draw()});more?.addEventListener('click',()=>{expanded=!expanded;draw()});draw();
  }

  function setupMap(){
    const host=$('#approvalMap');if(!host)return;if(typeof L==='undefined'){const lang=localStorage.getItem(langStore)||'en';host.innerHTML=`<div class="mapUnavailable">${lang==='ar'?'الخريطة التفاعلية غير متاحة. استخدم دليل الأسواق أدناه.':lang==='zh'?'交互式地图不可用。请使用下方市场目录。':'Interactive map unavailable. Please use the market directory below.'}</div>`;return;}
    map=L.map(host,{zoomControl:true,scrollWheelZoom:false,minZoom:2,maxZoom:6,worldCopyJump:true,attributionControl:true}).setView([18,28],3.25);
    // V34: use three independent tile providers. The first provider that
    // successfully serves tiles stays active; this is more reliable across
    // networks where one map CDN may be blocked or slow.
    const tileProviders=[
      {light:'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',dark:'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',attribution:'&copy; OpenStreetMap contributors'},
      {light:'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',dark:'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',attribution:'&copy; OpenStreetMap &copy; CARTO'},
      {light:'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',dark:'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',attribution:'&copy; Esri'}
    ];
    const isDark=document.documentElement.classList.contains('darkMode');
    let providerIndex=0;
    let activeTiles=null;
    let fallbackTimer=null;
    const showMapNotice=()=>{
      if(host.querySelector('.mapTileNotice'))return;
      const lang=localStorage.getItem(langStore)||'en';
      const msg=lang==='ar'?'خريطة الخلفية غير متاحة حاليًا. استخدم دليل الأسواق أدناه.':lang==='zh'?'地图底图暂时不可用，请使用下方市场目录。':'Map tiles are temporarily unavailable. Please use the market directory below.';
      const notice=document.createElement('div'); notice.className='mapTileNotice'; notice.textContent=msg; host.appendChild(notice);
    };
    const useProvider=(idx)=>{
      if(!map||idx>=tileProviders.length){showMapNotice();return;}
      providerIndex=idx;
      const cfg=tileProviders[idx];
      const layer=L.tileLayer(isDark?cfg.dark:cfg.light,{maxZoom:19,attribution:cfg.attribution,updateWhenIdle:true,keepBuffer:2});
      activeTiles=layer; layer.addTo(map);
      let settled=false;
      const advance=()=>{
        if(settled)return; settled=true;
        clearTimeout(fallbackTimer);
        try{map.removeLayer(layer)}catch(e){}
        useProvider(idx+1);
      };
      layer.once('load',()=>{settled=true;clearTimeout(fallbackTimer)});
      layer.once('tileerror',advance);
      fallbackTimer=setTimeout(()=>{
        if(!settled)advance();
      },7000);
    };
    useProvider(0);
    const markerIcon=L.divIcon({className:'afaq-map-marker',html:'<span></span>',iconSize:[18,18],iconAnchor:[9,9],popupAnchor:[0,-10]});
    Object.entries(countryByCode).forEach(([code,items])=>{
      const p=coords[code];if(!p)return;
      const lang=localStorage.getItem(langStore)||'en';const popupTitle=lang==='ar'?'مسارات الدول':lang==='zh'?'国家路径':'Country routes';const content=items.map(c=>`<a class="mapPopupLink" href="country.html?country=${encodeURIComponent(c.name)}"><span class="mapFlag">${countryFlagHtml(c)}</span><b>${esc(countryName(c,lang))}</b><em>${esc(c.authority)}</em><i>↗</i></a>`).join('');
      L.marker(p,{icon:markerIcon}).addTo(map).bindPopup(`<div class="mapPopup"><div class="popupEy">AFAQ JOOD</div><h3>${items.length>1?popupTitle:esc(countryName(items[0],lang))}</h3>${content}</div>`,{maxWidth:290,minWidth:220});
    });
    map.fitBounds([[-35,-20],[45,65]],{padding:[20,20]});
  }

  function applyLanguage(lang){
    lang=T[lang]?lang:'en';localStorage.setItem(langStore,lang);const d=T[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';if(!$('#countryPage'))document.title=d.pageTitle;const meta=document.querySelector('meta[data-meta-i18n]');if(meta&&d[meta.dataset.metaI18n]!==undefined)meta.setAttribute('content',d[meta.dataset.metaI18n]);
    $$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(d[k]!==undefined)el.textContent=d[k]});
    $$('[data-placeholder]').forEach(el=>{const k=el.dataset.placeholder;if(d[k])el.placeholder=d[k]});$$('[data-aria-i18n]').forEach(el=>{const k=el.dataset.ariaI18n;if(d[k]!==undefined)el.setAttribute('aria-label',d[k])});$$('[data-alt-i18n]').forEach(el=>{const k=el.dataset.altI18n;if(d[k]!==undefined)el.alt=d[k]});
    $$('.langBtn').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));
    const h=$('[data-i18n="heroTitle"]');if(h){const p=d.heroTitle.split('|');h.innerHTML=`${esc(p[0])}<br><span>${esc(p[1]||'')}</span>`}
    const st=serviceT[lang];if(st)Object.entries(st).forEach(([k,v])=>{const e=document.querySelector(`[data-i18n="${k}"]`);if(e)e.textContent=v});
    const more=$('#moreMarketsBtn span');if(more)more.textContent=d.moreMarkets;
    if(window.__afaqDrawCountries)window.__afaqDrawCountries();
    if(map){try{map.remove()}catch(e){}map=null;lightTiles=null;darkTiles=null;setupMap();}
    const top=$('#backTop');if(top)top.setAttribute('aria-label',lang==='ar'?'العودة إلى الأعلى':lang==='zh'?'返回顶部':'Back to top');
    if($('#countryPage'))renderCountry();
  }
  function setupLanguages(){$$('.langBtn').forEach(b=>b.addEventListener('click',()=>applyLanguage(b.dataset.lang)));applyLanguage(localStorage.getItem(langStore)||'en')}

